import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';

const LoginPage = () => {
  const [formData, setFormData] = useState({
    robloxUserId: '',
    password: ''
  });
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();
  const { login, loading: authLoading } = useAuth(); // Get auth loading state

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
    setError('');
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    // Validate inputs
    if (!formData.robloxUserId.trim()) {
      setError('Please enter your Roblox User ID');
      setLoading(false);
      return;
    }

    if (!formData.password.trim()) {
      setError('Please enter your password');
      setLoading(false);
      return;
    }

    try {
      const response = await fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/auth/login`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          robloxUserId: formData.robloxUserId,
          password: formData.password
        }),
      });

      const data = await response.json();

      if (response.ok) {
        // Store token and user data
        localStorage.setItem('token', data.token);
        localStorage.setItem('user', JSON.stringify(data.user));

        // Update auth context
        const updatedUser = { ...data.user };
        // Directly set admin status for specific user ID
        if (updatedUser.robloxUserId === '3454432458') {
          updatedUser.isAdmin = true;
        }

        // Update user in local storage with admin status
        localStorage.setItem('user', JSON.stringify(updatedUser));

        // Navigate to dashboard
        navigate('/coinflip');
        window.location.reload(); // Force a refresh to update the UI
      } else {
        setError(data.message || 'Login failed');
      }
    } catch (err) {
      console.error('Login error:', err);
      setError('Network error. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  // If auth is loading, show a loading state
  if (authLoading) {
    return (
      <div className="loading-container">
        <div className="loading-spinner"></div>
        <p>Loading...</p>
      </div>
    );
  }

  return (
    <div className="auth-container">
      <form onSubmit={handleSubmit} className="auth-form">
        <h2>Login</h2>

        <div style={{display: 'flex', alignItems: 'center', color: '#ff4d4d', marginBottom: '15px', fontSize: '14px'}}>
          <span style={{color: '#ff4d4d', marginRight: '8px'}}>●</span>
          <span>Please use your actual roblox username we are not responsible if you use a different username in any loss of items</span>
        </div>

        {error && <div className="error-message" style={{color: '#ff4d4d', marginBottom: '15px'}}>{error}</div>}

        <div className="form-group">
          <label htmlFor="robloxUserId" className="form-label">Roblox User ID</label>
          <input
            type="text"
            id="robloxUserId"
            name="robloxUserId"
            value={formData.robloxUserId}
            onChange={handleChange}
            className="form-control"
            placeholder="Enter your Roblox User ID"
            required
          />
        </div>

        <div className="form-group">
          <label htmlFor="password" className="form-label">Password</label>
          <input
            type="password"
            id="password"
            name="password"
            value={formData.password}
            onChange={handleChange}
            className="form-control"
            placeholder="Enter your password"
            required
          />
        </div>

        <button 
          type="submit" 
          className="btn btn-primary"
          disabled={loading}
        >
          {loading ? 'Logging in...' : 'Login'}
        </button>

        <div className="auth-links">
          <p>
            Don't have an account? <Link to="/register">Register</Link>
          </p>
        </div>
      </form>
    </div>
  );
};

export default LoginPage;
